58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Minimal syntactic check for an email address: a non-empty local part, a single
66	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final TelephoneNormalizer telephoneNormalizer;
79	
80	    private final AddressNormalizer addressNormalizer;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper,
86	                                 TelephoneNormalizer telephoneNormalizer,
87	                                 AddressNormalizer addressNormalizer) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	        this.telephoneNormalizer = telephoneNormalizer;
93	        this.addressNormalizer = addressNormalizer;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        if (owner.getRegistrationDate() == null) {
127	            owner.setRegistrationDate(LocalDate.now());
128	        }
129	        String address = addressNormalizer.normalize(owner.getAddress());
130	        if (address.isBlank()) {
131	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
132	        }
133	        owner.setAddress(address);
134	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
135	        if (telephone == null) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        owner.setTelephone(telephone);
139	        String email = owner.getEmail();
140	        if (email != null) {
141	            email = email.trim();
142	            if (!EMAIL_PATTERN.matcher(email).matches()) {
143	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
144	            }
145	            owner.setEmail(email.toLowerCase(Locale.ROOT));
146	        }
147	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
148	            .map(Owner::getTelephone)
149	            .filter(Objects::nonNull)
150	            .map(telephoneNormalizer::normalize)
151	            .anyMatch(telephone::equals);
152	        if (telephoneInUse) {
153	            return new ResponseEntity<>(HttpStatus.CONFLICT);
154	        }
155	        String lastNameKey = normalizeIdentity(owner.getLastName());
156	        String addressKey = addressNormalizer.normalize(owner.getAddress());
157	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
158	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
159	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
160	                    && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
161	            if (householdDuplicate) {
162	                return new ResponseEntity<>(HttpStatus.CONFLICT);
163	            }
164	        }
165	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
166	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
167	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
168	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
169	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
170	            .count();
171	        owner.setNamesakeCount(namesakeCount);
172	        this.clinicService.saveOwner(owner);
173	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
174	        headers.setLocation(UriComponentsBuilder.newInstance()
175	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
176	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    /**
180	     * Normalize a value for household-identity comparison: null becomes an empty
181	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
182	     * to a single space, and the result is lower-cased.
183	     */
184	    private static String normalizeIdentity(String value) {
185	        if (value == null) {
186	            return "";
187	        }
188	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
189	    }
190	
191	    /**
192	     * Build the stable, shared household identifier for an owner, formatted
193	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
194	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
195	     * Owners in the same household (same normalized lastName and address) therefore
196	     * derive an identical householdId.
197	     */
198	    private static String householdId(String lastNameKey, String addressKey) {
199	        String source = lastNameKey + "|" + addressKey;
200	        try {
201	            byte[] digest = MessageDigest.getInstance("SHA-256")
202	                .digest(source.getBytes(StandardCharsets.UTF_8));
203	            StringBuilder sb = new StringBuilder(digest.length * 2);
204	            for (byte b : digest) {
205	                sb.append(String.format("%02x", b));
206	            }
207	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
208	        }
209	        catch (NoSuchAlgorithmException e) {
210	            throw new IllegalStateException("SHA-256 not available", e);
211	        }
212	    }
213	
214	    /**
215	     * Build the customer code assigned on create, formatted {@code '<LAST3>-<NNNN>'}:
216	     * LAST3 is the upper-cased first three letters of {@code lastName} and NNNN is a
217	     * global 4-digit zero-padded sequence equal to one more than the current number of
218	     * owners (e.g. 'SMI-0007').
219	     */
220	    private String nextCustomerCode(String lastName) {
221	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
222	        int sequence = this.clinicService.findAllOwners().size() + 1;
223	        return String.format("%s-%04d", last3, sequence);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
229	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
230	        if (currentOwner == null) {
231	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	        }
233	        currentOwner.setAddress(ownerFieldsDto.getAddress());
234	        currentOwner.setCity(ownerFieldsDto.getCity());
235	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
236	        currentOwner.setLastName(ownerFieldsDto.getLastName());
237	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
238	        this.clinicService.saveOwner(currentOwner);
239	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Transactional
244	    @Override
245	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner == null) {
248	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	        }
250	        this.clinicService.deleteOwner(owner);
251	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
252	    }
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
257	        Owner owner = this.clinicService.findOwnerById(ownerId);
258	        if (owner == null) {
259	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	        }
261	        HttpHeaders headers = new HttpHeaders();
262	        Pet pet = petMapper.toPet(petFieldsDto);
263	        owner.setId(ownerId);
264	        pet.setOwner(owner);
